import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 기본 크기 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 열람 이력의 대상 정보 구분은 '급여', 접근 유형은 '시뮬레이션'
const INFO_TYPE = '급여';
const ACCESS_TYPE = '시뮬레이션';

// 가정: 현재 급여는 임직원별 가장 최근 지급일 급여의 총 지급액이다.
// 가정: 대상은 재직자만이다. 부서·임직원 조건이 모두 없으면 재직자 전체다.
// 가정: 총 지급액이 숫자로 읽히는 급여만 계산한다 (복호화 방식은 todos 참고).
const TARGET_CTE = `
  WITH cur AS (
    SELECT DISTINCT ON (p.employee_id)
      p.employee_id,
      CASE WHEN p.total_payment_amount_enc ~ '^[0-9]+([.][0-9]+)?$'
        THEN CAST(p.total_payment_amount_enc AS numeric)
      END AS pay
    FROM payroll p
    ORDER BY p.employee_id, p.pay_date DESC
  ), target AS (
    SELECT
      e.employee_id,
      ROUND(cur.pay * (1 + CAST(:raiseRate AS numeric)), 2) AS expected_pay
    FROM employee e
    JOIN cur ON cur.employee_id = e.employee_id
    WHERE e.employment_status = '재직자'
      AND cur.pay IS NOT NULL
      AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))
      AND (CAST(:ids AS text) IS NULL
        OR e.employee_id = ANY(CAST(string_to_array(CAST(:ids AS text), ',') AS bigint[])))
  )
`;

function invalid(message: string): ApiError {
  return new ApiError(422, 'INVALID_SIMULATION_CONDITION', message);
}

@Controller('api/v1')
export class FnSfr02107Controller {
  @Post('/payroll-simulations')
  @HttpCode(200)
  async simulatePayroll(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const query = checks.queryOf(req.query);

    const raiseRate = data['raiseRate'];
    if (typeof raiseRate !== 'number' || !Number.isFinite(raiseRate) || raiseRate <= -1) {
      throw invalid('인상률이 올바르지 않습니다. -100%보다 큰 숫자를 입력하세요.');
    }

    const rawDepartment = data['departmentId'];
    let departmentId: number | null = null;
    if (rawDepartment !== undefined && rawDepartment !== null && rawDepartment !== '') {
      if (typeof rawDepartment !== 'number' || !Number.isInteger(rawDepartment) || rawDepartment <= 0) {
        throw invalid('대상 부서가 올바르지 않습니다.');
      }
      departmentId = rawDepartment;
    }

    const rawIds = data['employeeIds'];
    let ids: string | null = null;
    if (rawIds !== undefined && rawIds !== null) {
      if (!Array.isArray(rawIds)) {
        throw invalid('대상 임직원 목록이 올바르지 않습니다.');
      }
      for (const id of rawIds) {
        if (typeof id !== 'number' || !Number.isInteger(id) || id <= 0) {
          throw invalid('대상 임직원 목록이 올바르지 않습니다.');
        }
      }
      if (rawIds.length > 0) {
        ids = rawIds.join(',');
      }
    }

    const page = query['page'] === undefined ? 0 : Number(query['page']);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    const sizeRaw = query['size'] === undefined ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, MAX_SIZE);

    return transaction(async (db) => {
      if (departmentId !== null) {
        const found = await db.query(
          'SELECT department_id FROM department WHERE department_id = CAST(:departmentId AS bigint)',
          { departmentId },
        );
        if (found.length === 0) {
          throw invalid('대상 부서를 찾을 수 없습니다.');
        }
      }

      const params = { raiseRate, departmentId, ids };

      const summary = await db.query(
        `${TARGET_CTE}
        SELECT COUNT(*) AS total, COALESCE(SUM(expected_pay), 0) AS "totalLaborCost"
        FROM target`,
        params,
      );
      const total = Number(summary[0]['total']);
      const totalLaborCost = Number(summary[0]['totalLaborCost']);

      const rows = await db.query(
        `${TARGET_CTE}
        SELECT employee_id AS "employeeId", expected_pay AS "expectedPay"
        FROM target
        ORDER BY employee_id
        LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...params, size, offset: page * size },
      );

      // 급여 개인정보 열람 이력: 계산에 쓴 임직원마다 한 건씩 남긴다.
      // 시뮬레이션 결과는 payroll에 저장하지 않는다.
      await db.execute(
        `${TARGET_CTE}
        INSERT INTO personal_info_access_log
          (employee_id, target_employee_id, target_info_type, access_type, accessed_at, access_ip, created_at, updated_at)
        SELECT CAST(:userId AS bigint), t.employee_id, :infoType, :accessType, now(), CAST(:ip AS varchar), now(), now()
        FROM target t`,
        {
          ...params,
          userId: user.id,
          infoType: INFO_TYPE,
          accessType: ACCESS_TYPE,
          ip: req.ip ?? null,
        },
      );

      return {
        items: rows.map((r: Record<string, unknown>) => ({
          employeeId: Number(r['employeeId']),
          expectedPay: Number(r['expectedPay']),
          totalLaborCost,
        })),
        page,
        size,
        total,
      };
    });
  }
}

