import { useState } from 'react';
import {
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  RefName,
  Tiles,
  call,
} from '../kit';
import type { PageProps } from '../kit';

interface SimItem {
  employeeId: number;
  expectedPay: number;
  totalLaborCost: number;
  [key: string]: unknown;
}

interface SimResult {
  items: SimItem[];
  page: number;
  size: number;
  total: number;
}

const PAGE_SIZE = 20;

export default function FnSfr02107Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [ratePercent, setRatePercent] = useState<number | string>('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [pickedId, setPickedId] = useState<number | string>('');
  const [employeeIds, setEmployeeIds] = useState<number[]>([]);
  const [condition, setCondition] = useState<Record<string, unknown> | undefined>(undefined);
  const [result, setResult] = useState<SimResult | undefined>(undefined);

  async function run(body: Record<string, unknown>, page: number) {
    const res = await call<SimResult>('POST', '/payroll-simulations', role, body, {
      page,
      size: PAGE_SIZE,
    });
    setCondition(body);
    setResult(res);
  }

  async function submit() {
    if (typeof ratePercent !== 'number') {
      throw new Error('인상률을 숫자로 입력하세요.');
    }
    const body: Record<string, unknown> = {
      raiseRate: Number((ratePercent / 100).toFixed(6)),
    };
    if (departmentId !== '') {
      body.departmentId = departmentId;
    }
    if (employeeIds.length > 0) {
      body.employeeIds = employeeIds;
    }
    await run(body, 0);
    setOpen(false);
    notify('급여 시뮬레이션을 계산했습니다. 결과는 실제 급여에 반영되지 않습니다.');
  }

  function addEmployee(value: number | string) {
    setPickedId('');
    if (typeof value !== 'number') {
      return;
    }
    if (employeeIds.includes(value)) {
      return;
    }
    setEmployeeIds([...employeeIds, value]);
  }

  function removeEmployee(id: number) {
    setEmployeeIds(employeeIds.filter((x) => x !== id));
  }

  const totalLaborCost = result && result.items.length > 0 ? result.items[0].totalLaborCost : 0;

  return (
    <div className="doc">
      <section className="box">
        <h2>급여 시뮬레이션</h2>
        <Band total={result?.total}>
          <button onClick={() => setOpen(true)}>시뮬레이션 실행</button>
        </Band>
        {result && (
          <Tiles
            items={[
              ['대상 인원', <Num value={result.total} />],
              ['예상 인건비 합계', <Num value={totalLaborCost} />],
            ]}
          />
        )}
        <DataTable<SimItem>
          columns={[
            {
              key: 'employeeId',
              label: '임직원',
              render: (row) => <RefName table="employee" role={role} value={row.employeeId} />,
            },
            {
              key: 'expectedPay',
              label: '예상 급여',
              render: (row) => <Num value={row.expectedPay} />,
            },
          ]}
          rows={result ? result.items : []}
          empty="아직 계산한 결과가 없습니다. 시뮬레이션 실행을 눌러 조건을 입력하세요."
        />
        {result && condition && (
          <Pager
            page={result.page}
            size={result.size}
            total={result.total}
            onPage={(p) => {
              run(condition, p).catch((e: unknown) => {
                notify(e instanceof Error ? e.message : '결과를 불러오지 못했습니다.');
              });
            }}
          />
        )}
      </section>
      {open && (
        <Drawer title="급여 시뮬레이션 조건" onClose={() => setOpen(false)}>
          <Form
            onSubmit={submit}
            submit="계산하기"
            note="계산 결과는 저장되지 않으며, 급여 개인정보 열람 이력이 남습니다."
          >
            <Field label="인상률(%)" required hint="예: 3을 입력하면 3% 인상입니다.">
              <NumberInput value={ratePercent} onChange={setRatePercent} />
            </Field>
            <Field label="대상 부서" hint="비워 두면 재직자 전체가 대상입니다.">
              <LookupSelect
                table="department"
                role={role}
                value={departmentId}
                onChange={setDepartmentId}
                placeholder="전체 부서"
              />
            </Field>
            <Field label="대상 임직원 ID 목록" wide hint="고르면 목록에 추가됩니다.">
              <LookupSelect
                table="employee"
                role={role}
                value={pickedId}
                onChange={addEmployee}
                placeholder="임직원 추가"
              />
              <div>
                {employeeIds.map((id) => (
                  <span key={id}>
                    <RefName table="employee" role={role} value={id} />
                    <button type="button" className="ghost" onClick={() => removeEmployee(id)}>
                      제거
                    </button>
                  </span>
                ))}
              </div>
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
